package org.brightstats.desktop;
import java.util.*;
import javafx.geometry.Insets;
import javafx.scene.Node;
import javafx.scene.control.*;
import javafx.scene.layout.*;

final class ReportPresentation {
    private ReportPresentation(){}
    static void navigation(BorderPane border,TabPane tabs){
        if(border.getLeft()!=null)return;
        TextField search=new TextField();search.setPromptText("Find a report section");search.setAccessibleText("Search report section names");TreeView<Tab> tree=new TreeView<>();tree.setShowRoot(false);tree.setCellFactory(ignore->new TreeCell<>(){protected void updateItem(Tab tab,boolean empty){super.updateItem(tab,empty);setText(empty||tab==null?null:tab.getText());setTooltip(empty||tab==null?null:new Tooltip(tab.getText()));}});
        Runnable refresh=()->{String query=search.getText().strip().toLowerCase(Locale.ROOT);TreeItem<Tab> root=new TreeItem<>();for(Tab tab:tabs.getTabs())if(query.isEmpty()||tab.getText().toLowerCase(Locale.ROOT).contains(query))root.getChildren().add(new TreeItem<>(tab));tree.setRoot(root);};
        search.textProperty().addListener((o,a,b)->refresh.run());tabs.getTabs().addListener((javafx.collections.ListChangeListener<Tab>)change->refresh.run());tree.getSelectionModel().selectedItemProperty().addListener((o,a,b)->{if(b!=null)tabs.getSelectionModel().select(b.getValue());});
        VBox navigation=new VBox(8,new Label("REPORT EXPLORER"),search,tree);navigation.getStyleClass().add("report-explorer");navigation.setPrefWidth(UiAppearance.current().layout()==org.brightstats.data.UserPreferences.Layout.PRESENTATION?170:215);navigation.setMinWidth(150);navigation.setStyle("-fx-padding:10;");VBox.setVgrow(tree,Priority.ALWAYS);border.setLeft(navigation);refresh.run();
    }
    static void decorate(Node content){if(!(content instanceof BorderPane border)||!(border.getCenter() instanceof TabPane tabs)||border.getProperties().containsKey("brightstats.outline"))return;border.getProperties().put("brightstats.outline",true);Node previous=border.getTop();border.setTop(null);ComboBox<Tab> sections=new ComboBox<>();sections.getItems().setAll(tabs.getTabs());tabs.getTabs().addListener((javafx.collections.ListChangeListener<Tab>)change->{Tab selected=tabs.getSelectionModel().getSelectedItem();sections.getItems().setAll(tabs.getTabs());sections.getSelectionModel().select(selected);});sections.setMaxWidth(Double.MAX_VALUE);sections.setConverter(new javafx.util.StringConverter<>(){public String toString(Tab tab){return tab==null?"":tab.getText();}public Tab fromString(String value){return null;}});sections.getSelectionModel().select(tabs.getSelectionModel().getSelectedItem());sections.setAccessibleText("Report section");sections.valueProperty().addListener((observable,old,value)->{if(value!=null)tabs.getSelectionModel().select(value);});tabs.getSelectionModel().selectedItemProperty().addListener((observable,old,value)->sections.getSelectionModel().select(value));HBox outline=new HBox(8,UiAppearance.label("Report section"),sections);outline.getStyleClass().add("report-outline");HBox.setHgrow(sections,Priority.ALWAYS);VBox top=new VBox(4);if(previous instanceof Label label&&label.getText()!=null&&label.getText().contains("\n")){String[] parts=label.getText().split("\n",2);Label title=UiAppearance.label(parts[0]);title.setWrapText(true);title.setPadding(new Insets(8));Label detail=UiAppearance.label(parts[1]);detail.setWrapText(true);detail.setMaxWidth(900);ScrollPane scroll=new ScrollPane(detail);scroll.setFitToWidth(true);scroll.setPrefViewportHeight(170);TitledPane extra=new TitledPane(UiAppearance.text("Details and assumptions"),scroll);extra.setExpanded(false);extra.getStyleClass().add("diagnostic-details");top.getChildren().addAll(title,extra);}else if(previous!=null)top.getChildren().add(previous);top.getChildren().add(outline);border.setTop(top);navigation(border,tabs);ChartTools.install(content);tabs.getSelectionModel().selectedItemProperty().addListener((o,a,b)->{if(b!=null){ChartTools.install(b.getContent());UiMotion.reveal(b.getContent());}});UiAppearance.refresh(content);}
}
